// Liefert Gespraechs-Historie einer Session (paginiert, neueste zuerst geholt,
// chronologisch zurueckgegeben). Polling-frei: wird nur beim Laden/Blaettern gerufen.
const q = $('History Webhook').first().json.query || {};
const sid = q.session_id || '';
const before = parseInt(q.before_id || '0', 10) || 0;
const limit = Math.min(parseInt(q.limit || '30', 10) || 30, 100);
if (!sid) return [{ json: { messages: [] } }];
let url = '{{SUPABASE_URL}}/rest/v1/conversations?session_id=eq.' + encodeURIComponent(sid)
  + '&select=id,role,content,created_at,metadata&order=id.desc&limit=' + Math.min(limit * 2, 200);
if (before > 0) url += '&id=lt.' + before;
const rows = await helpers.httpRequest({ method: 'GET', url, headers: { 'apikey': '{{SUPABASE_SERVICE_KEY}}' } });
// Geplante Laeufe (Erinnerung mit Auftrag, Nachfrage zu offenen Vorhaben) legen
// ihren Auftrag als user-Zeile ab, damit Rupert ihn im Verlauf sieht. In der
// Weboberflaeche stand er dann wie eine Nachricht der Person da ("Du fragst
// proaktiv beim User ..."). Angezeigt wird nur Ruperts Antwort (Runde 10,
// 19.10.2026). Geholt wird die doppelte Menge, damit eine volle Seite auch nach
// dem Aussortieren voll bleibt: die Oberflaeche blaettert nur weiter, wenn
// genau limit Nachrichten kommen. oldest_id ist die aelteste gelieferte
// Nachricht, die naechste Seite schliesst direkt an.
const GEPLANT = ['scheduled_action', 'scheduled_task'];
const alle = Array.isArray(rows) ? rows.slice().reverse() : [];
const sichtbar = alle.filter(r => !(r && r.role === 'user' && r.metadata && GEPLANT.includes(r.metadata.source)));
const list = sichtbar.slice(-limit).map(r => ({ id: r.id, role: r.role, content: r.content, created_at: r.created_at }));
return [{ json: { messages: list, oldest_id: list.length ? list[0].id : null } }];
